"""Curated, text-first course. Answer keys remain on the server."""

def question(prompt, options, answer, explanation):
    return dict(prompt=prompt, options=options, answer=answer, explanation=explanation)

COURSE = [
    ('Data fundamentals', 'Inspect tabular datasets', [
        ('Meet your first dataset', 'Understand rows, columns, and the questions hiding in your data.', 'A dataset is an organized collection of observations. In a table, each row usually represents one observation and each column describes an attribute.\n\nImagine a shop with columns Order ID, Customer, Amount, and Date. Each row describes one order. The Amount column is numeric; Customer is categorical.\n\nBefore calculating anything, ask: What does one row represent? What units are used? What question do I need to answer?', [question('One row in this shop dataset represents…', ['A column name', 'One order', 'Every customer'], 1, 'Each row is one observation: an order.'), question('Which column is numeric?', ['Customer', 'Date label', 'Amount'], 2, 'Amount contains numerical measurements.')]),
        ('Ask a useful data question', 'Turn a broad business goal into something you can measure.', 'A useful analytical question names a measure and a comparison. “How is the shop doing?” is broad. “How did total weekly revenue change from last week?” is measurable.\n\nRevenue is the sum of sales amounts, not profit. Profit also accounts for costs. Choose the measure that matches the decision.\n\nFor sales of 120, 80, and 100, total revenue is 300. The mean sale is 100.', [question('Total revenue for 120, 80, and 100 is…', ['100', '200', '300'], 2, '120 + 80 + 100 = 300.'), question('Which question is measurable?', ['Are we amazing?', 'How did weekly revenue change?', 'Is data good?'], 1, 'It identifies a measure and a comparison.')])]),
    ('Spreadsheet analysis', 'Use spreadsheet formulas', [
        ('Make formulas work for you', 'Use cell references and simple calculations.', 'A spreadsheet formula begins with =. If B2 contains 120 and C2 contains 3, =B2*C2 returns 360.\n\nRelative references move when copied. Copying =B2*C2 down one row changes it to =B3*C3.\n\nAn absolute reference uses dollar signs. $F$1 keeps both its column and row fixed. In =B2*$F$1, copying down changes B2 but keeps $F$1. This is useful for a fixed tax rate.', [question('Copy =B2*C2 down one row. What is the formula?', ['=B3*C3', '=B2*C2', '=C2*D2'], 0, 'Relative references move down one row.'), question('Which reference stays fully fixed?', ['F1', '$F$1', 'F2'], 1, 'Dollar signs fix the column and row.')]),
        ('Summarize a column', 'Calculate totals and averages with confidence.', 'SUM adds numeric values in a range. =SUM(B2:B4) adds cells B2, B3, and B4. AVERAGE divides the sum of numeric values by their count.\n\nFor 10, 20, and 30, the sum is 60 and the average is 20. Empty cells and zeros are different: a zero is a value and contributes to the count in an average.\n\nCheck the range before you trust a result. Including a total row can count the same values twice.', [question('AVERAGE of 10, 20, 30 is…', ['60', '20', '30'], 1, '60 divided by 3 = 20.'), question('What can double-count values?', ['Excluding a title', 'Including the total row in SUM', 'Using a numeric column'], 1, 'The total already includes the values above it.')])]),
    ('Data cleaning', 'Handle missing values and duplicates', [
        ('Find what is missing', 'Distinguish missing information from a real zero.', 'A missing value means information is not available. It does not automatically mean zero. Replacing a missing sale with zero changes the average and may mislead a decision.\n\nStart by counting missing values and looking for patterns. Check whether a source can supply the missing information. If you remove rows or fill values, record your rule and why it fits the context.\n\nFor sales 10, 20, and an unknown value, the mean of known sales is 15. Treating the unknown value as zero gives 10, a different claim.', [question('A blank sale should always become zero.', ['True', 'False', 'Only on Monday'], 1, 'Missing information is not necessarily a zero sale.'), question('The mean of known sales 10 and 20 is…', ['10', '15', '30'], 1, '(10 + 20) / 2 = 15.')]),
        ('Clean a customer dataset', 'Choose a meaningful key before removing duplicates.', 'Duplicate rows can inflate totals. But two customers with the same name are not necessarily the same person. Use a stable identifier, such as Customer ID, when deciding whether records refer to the same entity.\n\nExample: ID 101, Ada, 50; ID 101, Ada, 50; ID 102, Ada, 70. The first two rows are exact duplicates. The third row has a different ID and should remain.\n\nKeep the original data, document your changes, and compare row counts before and after cleaning.', [question('Which rows are exact duplicates in the example?', ['First and second', 'All three', 'Second and third'], 0, 'The first two have identical IDs, names, and values.'), question('After removing the exact duplicate, the total is…', ['170', '120', '50'], 1, '50 + 70 = 120.')])]),
    ('SQL foundations', 'Query and aggregate data', [
        ('Select the data you need', 'Read a simple query and filter rows.', 'SQL lets you ask questions of relational tables. SELECT chooses columns, FROM identifies the table, and WHERE filters rows.\n\nSELECT customer, amount FROM orders WHERE amount > 100;\n\nThis returns the customer and amount for orders with an amount greater than 100. An order of exactly 100 is excluded. Use >= to include that boundary.', [question('Which clause filters rows?', ['SELECT', 'WHERE', 'FROM'], 1, 'WHERE applies conditions to rows.'), question('amount > 100 includes an amount of exactly 100.', ['True', 'False'], 1, 'The strict greater-than operator excludes 100.')]),
        ('Group and aggregate', 'Move from individual orders to useful summaries.', 'Aggregate functions summarize values. SUM(amount) calculates total sales. COUNT(*) counts rows. GROUP BY produces a result for each group.\n\nSELECT region, SUM(amount) FROM orders GROUP BY region;\n\nThis returns one row per region with its total sales. WHERE filters individual rows before grouping. HAVING filters groups after aggregation.', [question('To return one total per region, use…', ['GROUP BY region', 'ORDER BY amount', 'SELECT * only'], 0, 'GROUP BY defines the groups to summarize.'), question('Which function counts rows?', ['SUM(amount)', 'COUNT(*)', 'AVG(amount)'], 1, 'COUNT(*) counts the rows in each group.')])]),
    ('Data visualization', 'Create appropriate visualizations', [
        ('Choose the right chart', 'Match the visual to the question.', 'A bar chart compares categories. A line chart is useful for trends across ordered time points. A scatter plot shows the relationship between two numeric variables.\n\nTo compare total revenue across regions, use a bar chart. To show monthly revenue over a year, use a line chart.\n\nLabel axes and units. For bar charts, a zero baseline generally preserves the meaning of bar length. Avoid unnecessary decoration that obscures the values.', [question('Compare revenue across regions with…', ['A bar chart', 'A map without values', 'A paragraph only'], 0, 'Bars make category comparisons easy.'), question('A trend across months is well suited to…', ['A line chart', 'A pie for each day', 'A random arrangement'], 0, 'The line follows the ordered time points.')]),
        ('Tell an honest story', 'Explain a finding without overstating it.', 'A chart is evidence for a claim. Give the reader context: the time period, unit, source, and any missing information.\n\nIf revenue increased from 200 to 250, the absolute increase is 50 and the percentage increase is 25%. The original value is the denominator.\n\nTwo things moving together does not prove that one caused the other. A good summary distinguishes an observation from a causal explanation.', [question('Revenue grows from 200 to 250. Growth is…', ['50%', '25%', '20%'], 1, '50 / 200 × 100 = 25%.'), question('Correlation always proves causation.', ['True', 'False'], 1, 'A shared trend alone does not establish cause.')])]),
    ('Applied challenge', 'Explain a decision with evidence', [
        ('From messy data to insight', 'Combine inspection, cleaning, and analysis.', 'Your shop data has four records: A, North, 100; B, South, 80; A, North, 100; C, North, 120. The first field is the unique order ID.\n\nThe repeated order A is a duplicate. After removing it, North totals 220 and South totals 80. Total revenue is 300.\n\nNorth contributes about 73.3% of revenue. This describes the sample; it does not explain why the regions differ. To investigate, examine customer counts and the time period.', [question('Clean total revenue is…', ['400', '300', '220'], 1, '100 + 80 + 120 = 300.'), question('North revenue after cleaning is…', ['320', '220', '100'], 1, 'The unique North orders total 220.')]),
        ('Present your recommendation', 'Make a defensible decision and state its limits.', 'A useful analytical summary has three parts: finding, evidence, and next action.\n\nFinding: North generated more revenue in this sample. Evidence: 220 versus 80 after removing one duplicate order. Next action: compare customer counts and revenue per customer before deciding how to allocate marketing spend.\n\nAvoid claiming that the region itself caused the difference. Acknowledge the small sample and check that the period is representative.', [question('Which next action best follows the evidence?', ['Spend everything in North immediately', 'Compare customer counts and revenue per customer', 'Ignore duplicates'], 1, 'More context is needed before a spending decision.'), question('Which limitation matters here?', ['The sample is small', 'The table uses columns', 'The sum is numeric'], 0, 'A small sample may not represent typical performance.')])])
]

